do $$ declare src text:='https://meslek.meb.gov.tr/upload/cop9_mem/2021_kimya_mem_cop.pdf'; begin
insert into course_catalog(name,category) select x,'uygulama' from unnest(array['Kimya Teknolojisine Giriş','Temel Kimya','Boya Üretimi','Boyada Kalite Kontrol İşlemleri','Organik ve Polimer Kimya','Yaş Boya Testleri','Deri Üretim Teknolojisi','Ham Deri','Deri Atıkları','Deri Analizleri','Kürk Teknolojisi','Çimento Üretimi','Çimento Analizleri','Yapı Kimyasalları Üretimi','Kâğıt Üretimi Teknik Resim','Kâğıt Hamuru Hazırlama','Kâğıt Analizleri','Kâğıt İşleme','Temizlik Kâğıdı Üretimi','Temizlik Maddeleri ve Üretimi','Kozmetik Ürünleri ve Üretimi']) x where not exists(select 1 from course_catalog c where c.name=x);
insert into official_curriculum_profiles(effective_academic_year,school_type,program_type,field_name,branch_name,grade_level,required_course_count,required_hour_total,elective_course_min,elective_course_max,elective_hour_min,elective_hour_max,total_hour_min,total_hour_max,total_hour_target,group_rules,source_file_name,source_decision_no,source_note,active,schedule_variant,common_hours,vocational_hours,elective_vocational_hours,elective_hours,guidance_hours,enterprise_hours,applicability_status,source_page,parsed_constraints,academic_support_hours)
select '2026-2027','MESEM','MESEM','Kimya Teknolojisi',br,g,0,case when vv='USTALIK' then case g when 9 then 40 else 42 end else case g when 9 then 42 when 10 then 44 when 11 then 46 else 48 end end,0,0,0,case when g=9 then 2 else 0 end,case when vv='USTALIK' then 42 else case g when 9 then 44 when 10 then 44 when 11 then 46 else 48 end end,case when vv='USTALIK' then 42 else case g when 9 then 44 when 10 then 44 when 11 then 46 else 48 end end,case when vv='USTALIK' then 42 else case g when 9 then 44 when 10 then 44 when 11 then 46 else 48 end end,'[]'::jsonb,src,'2021-33','Parantezli temel ders saatleri diploma programı için ilave fark dersleridir.',true,vv,case when vv='USTALIK' then case g when 9 then 6 when 10 then 6 when 11 then 3 else 2 end else case g when 9 then 8 when 10 then 8 when 11 then 7 else 8 end end,case g when 9 then 2 when 10 then 4 when 11 then 7 else 8 end,0,case when g=9 then 2 else 0 end,0,32,'CURRENTLY_VALID',case br when 'Boya Üretimi ve Kontrolü' then 7 when 'Deri İşleme' then 8 when 'Çimento ve Yapı Kimyasalları Üretimi' then 9 when 'Kağıt Üretimi' then 10 else 11 end,'{"enterpriseDays":4,"enterpriseHoursPerDay":8,"parentheticalHoursMeaning":"DIPLOMA_ADDITIONAL_DIFFERENCE_COURSES"}'::jsonb,0
from unnest(array['Boya Üretimi ve Kontrolü','Deri İşleme','Çimento ve Yapı Kimyasalları Üretimi','Kağıt Üretimi','Temizlik, Kozmetik ve Parfümeri Ürünleri Üretimi']) q(br) cross join generate_series(9,12) gg(g) cross join unnest(array['USTALIK','DIPLOMA']) x(vv) where not exists(select 1 from official_curriculum_profiles p where p.effective_academic_year='2026-2027' and p.program_type='MESEM' and p.field_name='Kimya Teknolojisi' and p.branch_name=br and p.grade_level=g and p.schedule_variant=vv and p.active);
insert into official_course_schedule_catalog(effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,field_name,branch_name,parsed_constraints,source_decision_no,source_page,parser_confidence,needs_review,schedule_variant)
select '2026-2027','MESEM','MESEM',s.grade_level,s.course_id,s.category,s.hour_options,s.max_selections,s.repeat_across_years,src,'Kimya 2021-33 ortak temel/İME.',true,'Kimya Teknolojisi',br,s.parsed_constraints,'2021-33',case br when 'Boya Üretimi ve Kontrolü' then 7 when 'Deri İşleme' then 8 when 'Çimento ve Yapı Kimyasalları Üretimi' then 9 when 'Kağıt Üretimi' then 10 else 11 end,1,false,s.schedule_variant from official_course_schedule_catalog s join course_catalog c on c.id=s.course_id cross join unnest(array['Boya Üretimi ve Kontrolü','Deri İşleme','Çimento ve Yapı Kimyasalları Üretimi','Kağıt Üretimi','Temizlik, Kozmetik ve Parfümeri Ürünleri Üretimi']) q(br) where s.effective_academic_year='2026-2027' and s.program_type='MESEM' and s.field_name='Ayakkabı ve Saraciye Teknolojisi' and s.branch_name='Ayakkabı Modelistliği' and s.active and c.name in ('Türk Dili ve Edebiyatı','Din Kültürü ve Ahlak Bilgisi','Matematik','Tarih','T.C. İnkılap Tarihi ve Atatürkçülük','İşletmelerde Mesleki Eğitim') and not exists(select 1 from official_course_schedule_catalog z where z.effective_academic_year='2026-2027' and z.program_type='MESEM' and z.field_name='Kimya Teknolojisi' and z.branch_name=br and z.grade_level=s.grade_level and z.schedule_variant=s.schedule_variant and z.course_id=s.course_id and z.active);
create temporary table _k(br text,g int,n text,h int) on commit drop; insert into _k values
('Boya Üretimi ve Kontrolü',9,'Kimya Teknolojisine Giriş',2),('Boya Üretimi ve Kontrolü',10,'Temel Kimya',4),('Boya Üretimi ve Kontrolü',11,'Boya Üretimi',3),('Boya Üretimi ve Kontrolü',11,'Organik ve Polimer Kimya',4),('Boya Üretimi ve Kontrolü',12,'Ahilik Kültürü ve Girişimcilik',1),('Boya Üretimi ve Kontrolü',12,'Boyada Kalite Kontrol İşlemleri',3),('Boya Üretimi ve Kontrolü',12,'Yaş Boya Testleri',4),('Deri İşleme',9,'Kimya Teknolojisine Giriş',2),('Deri İşleme',10,'Temel Kimya',4),('Deri İşleme',11,'Deri Üretim Teknolojisi',7),('Deri İşleme',12,'Ahilik Kültürü ve Girişimcilik',1),('Deri İşleme',12,'Organik Kimya',2),('Deri İşleme',12,'Ham Deri',1),('Deri İşleme',12,'Deri Atıkları',1),('Deri İşleme',12,'Deri Analizleri',2),('Deri İşleme',12,'Kürk Teknolojisi',1),('Çimento ve Yapı Kimyasalları Üretimi',9,'Kimya Teknolojisine Giriş',2),('Çimento ve Yapı Kimyasalları Üretimi',10,'Temel Kimya',4),('Çimento ve Yapı Kimyasalları Üretimi',11,'Çimento Üretimi',4),('Çimento ve Yapı Kimyasalları Üretimi',11,'Çimento Analizleri',3),('Çimento ve Yapı Kimyasalları Üretimi',12,'Ahilik Kültürü ve Girişimcilik',1),('Çimento ve Yapı Kimyasalları Üretimi',12,'Yapı Kimyasalları Üretimi',7),('Kağıt Üretimi',9,'Kimya Teknolojisine Giriş',2),('Kağıt Üretimi',10,'Temel Kimya',4),('Kağıt Üretimi',11,'Kâğıt Üretimi Teknik Resim',1),('Kağıt Üretimi',11,'Kâğıt Hamuru Hazırlama',3),('Kağıt Üretimi',11,'Kâğıt Analizleri',3),('Kağıt Üretimi',12,'Ahilik Kültürü ve Girişimcilik',1),('Kağıt Üretimi',12,'Kâğıt İşleme',4),('Kağıt Üretimi',12,'Temizlik Kâğıdı Üretimi',3),('Temizlik, Kozmetik ve Parfümeri Ürünleri Üretimi',9,'Kimya Teknolojisine Giriş',2),('Temizlik, Kozmetik ve Parfümeri Ürünleri Üretimi',10,'Temel Kimya',4),('Temizlik, Kozmetik ve Parfümeri Ürünleri Üretimi',11,'Temizlik Maddeleri ve Üretimi',7),('Temizlik, Kozmetik ve Parfümeri Ürünleri Üretimi',12,'Ahilik Kültürü ve Girişimcilik',1),('Temizlik, Kozmetik ve Parfümeri Ürünleri Üretimi',12,'Kozmetik Ürünleri ve Üretimi',7);
insert into official_course_schedule_catalog(effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,field_name,branch_name,parsed_constraints,source_decision_no,source_page,parser_confidence,needs_review,schedule_variant) select '2026-2027','MESEM','MESEM',k.g,c.id,'uygulama',array[k.h]::smallint[],1,false,src,'Resmî Kimya 2021-33.',true,'Kimya Teknolojisi',k.br,'{}'::jsonb,'2021-33',case k.br when 'Boya Üretimi ve Kontrolü' then 7 when 'Deri İşleme' then 8 when 'Çimento ve Yapı Kimyasalları Üretimi' then 9 when 'Kağıt Üretimi' then 10 else 11 end,1,false,vv from _k k join course_catalog c on c.name=k.n cross join unnest(array['USTALIK','DIPLOMA']) x(vv) where not exists(select 1 from official_course_schedule_catalog z where z.effective_academic_year='2026-2027' and z.program_type='MESEM' and z.field_name='Kimya Teknolojisi' and z.branch_name=k.br and z.grade_level=k.g and z.schedule_variant=vv and z.course_id=c.id and z.active);
end $$;